// Curriculum progress is an explicit learner assessment, separate from scored question history.
state.learning=state.learning&&typeof state.learning==='object'?state.learning:{};
state.targets=state.targets&&typeof state.targets==='object'?state.targets:{};
let curriculumExam=exam;
let curriculumUnit=state.targets[exam]??catalogs[exam].units[0], curriculumQuery='', curriculumFilter='all';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const targetItems=()=>curriculum.filter(t=>t.exam===exam&&String(t.unit)===String(curriculumUnit));
const progressOf=t=>state.learning[t.id]?.status||0;
const relatedQuestions=t=>(t.questions||[]).map(id=>questions.find(q=>q.id===id)).filter(Boolean);
const statusNames=['未着手','学習中','自己確認済み'];
function normalizeTarget(){if(curriculumExam!==exam){curriculumExam=exam;curriculumUnit=state.targets[exam]??catalogs[exam].units[0];curriculumQuery='';curriculumFilter='all'}if(!catalogs[exam].units.some(u=>String(u)===String(curriculumUnit)))curriculumUnit=state.targets[exam]??catalogs[exam].units[0]}
function setTarget(unit){curriculumUnit=catalogs[exam].units.find(u=>String(u)===String(unit))??catalogs[exam].units[0];state.targets[exam]=curriculumUnit;level=curriculumUnit;queue=[];save();renderFilters();renderDashboard();renderCurriculum()}
function progressSummary(){normalizeTarget();const items=targetItems();return {items,total:items.length,started:items.filter(t=>progressOf(t)>0).length,checked:items.filter(t=>progressOf(t)===2).length,linked:items.filter(t=>relatedQuestions(t).length).length}}
function renderCurriculum(){normalizeTarget();const host=$('curriculumbody');if(!host)return;const s=progressSummary(),meta=curriculumSources[exam==='nissho'?'nissho2026':exam==='zenkei'?'zenkei2024':'aicpa2026'];
 host.innerHTML=`<div class="curriculum-intro"><span class="eyebrow">${esc(catalogs[exam].name)} / LEARNING MAP</span><h1>学ぶ全体像を、見失わない。</h1><p>級・科目から論点を選び、学ぶ順序と残りの範囲を確認する。</p><div class="map-controls"><label>学習する級・科目<select id="curriculumunit">${catalogs[exam].units.map(u=>`<option value="${u}" ${String(u)===String(curriculumUnit)?'selected':''}>${esc(unitLabel(u))}</option>`).join('')}</select></label><label>論点を探す<input id="curriculumsearch" type="search" value="${esc(curriculumQuery)}" placeholder="例：連結 / 棚卸 / leases"></label><label>表示する項目<select id="curriculumfilter"><option value="all">すべての項目</option><option value="new">未着手</option><option value="learning">学習中</option><option value="checked">自己確認済み</option><option value="noexercise">演習未収録</option></select></label></div><div class="scope-metrics"><div><strong>${s.total}</strong><span>学習チェック項目</span></div><div><strong>${s.started}</strong><span>着手した項目</span></div><div><strong>${s.checked}</strong><span>自己確認済み</span></div><div><strong>${s.linked} / ${s.total}</strong><span>関連演習のある項目</span></div></div><div class="progressbar"><i style="width:${s.total?s.checked/s.total*100:0}%"></i></div><p class="scope-note">学習チェックは自己申告です。演習成績・合格可能性とは別に管理します。上位級の一覧には基礎項目も含めています。</p>${exam==='uscpa'?'<p class="scope-note">FAR・AUD・REGが必須。BAR・ISC・TCPは1科目を選択して受験します。科目間に進級の関係はありません。</p>':''}<details class="source-box" ${exam==='zenkei'?'open':''}><summary>${esc(meta.title)} / 出典・確認状況${exam==='zenkei'?'（最終照合未完）':''}</summary><p>${esc(meta.note)}</p><p>確認日：${esc(meta.checked)}　<a href="${esc(meta.url)}" target="_blank" rel="noopener">公式資料を開く ↗</a></p></details></div><div class="sectiontitle"><h2>論点別カリキュラム</h2><button class="textbtn" id="curriculumexport">一覧をCSVで保存 ↓</button></div><div id="curriculumresults"></div><div id="lessonpanel"></div>`;
 $('curriculumfilter').value=curriculumFilter;$('curriculumunit').onchange=e=>setTarget(e.target.value);$('curriculumsearch').oninput=e=>{curriculumQuery=e.target.value;renderCurriculumResults()};$('curriculumfilter').onchange=e=>{curriculumFilter=e.target.value;renderCurriculumResults()};$('curriculumexport').onclick=exportCurriculum;renderCurriculumResults();
}
function filteredItems(){const query=curriculumQuery.trim().toLocaleLowerCase();return targetItems().filter(t=>(!query||(t.title+' '+t.area).toLocaleLowerCase().includes(query))&&(curriculumFilter==='all'||curriculumFilter==='new'&&progressOf(t)===0||curriculumFilter==='learning'&&progressOf(t)===1||curriculumFilter==='checked'&&progressOf(t)===2||curriculumFilter==='noexercise'&&!relatedQuestions(t).length))}
function renderCurriculumResults(){const host=$('curriculumresults');if(!host)return;const items=filteredItems(),groups=new Map();items.forEach(t=>{if(!groups.has(t.area))groups.set(t.area,[]);groups.get(t.area).push(t)});host.innerHTML=`<p class="muted" role="status">${items.length}項目を表示 / ${targetItems().length}項目</p>`+(items.length?Array.from(groups).map(([area,list],i)=>`<details class="curriculum-group" ${(curriculumQuery||curriculumFilter!=='all'||i===0)?'open':''}><summary><span>${esc(area)}</span><small>${list.filter(t=>progressOf(t)===2).length} / ${list.length} 自己確認済み</small></summary><div>${list.map(t=>`<button class="topic-row" data-lesson="${t.id}"><span class="topic-icon stage-${progressOf(t)}">${['○','◐','✓'][progressOf(t)]}</span><span class="topic-text"><b>${esc(t.title)}</b><small>${statusNames[progressOf(t)]}${t.scope==='pending'?' / 級別範囲の最終照合待ち':''}</small></span><span class="exercise-tag">${relatedQuestions(t).length?'関連演習 '+relatedQuestions(t).length+'問':'演習未収録'}</span><span>↗</span></button>`).join('')}</div></details>`).join(''):'<div class="panel empty">該当する項目がありません。検索語か表示条件を変更してください。</div>');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson))}
function learningPrompts(t){const title=t.title.toLowerCase();if(t.exam==='uscpa'&&t.unit==='AUD'||/監査|統制|soc|security|threat|mitigation|privacy|incident/i.test(title))return ['制度・業務の目的と、担当者の責任を説明する','事例のリスクを見つけ、必要な証拠・手続・統制を選ぶ','判断の根拠と、他の選択肢が適切でない理由を説明する'];if(/税|tax|basis|deduction|income|credits/.test(title))return ['適用される納税主体・税目・年度と、問題の前提を確認する','会計上の金額と税務上の金額を区別して計算する','例外・制限・繰越しの有無を確認し、処理を説明する'];if(/原価|差異|配賦|分析|予算|cost|budget|valuation|investment/.test(title))return ['目的に合う原価概念・計算方法を選ぶ','与えられた数量・単価・操業度から計算過程を組み立てる','算定結果の意味と、条件が変わった場合の影響を説明する'];return ['用語の意味と、取引・制度の目的を自分の言葉で説明する','認識・測定・記帳・表示の順序と、適用条件を整理する','資料から必要な情報を選び、処理の根拠を説明する']}
function openLesson(id){const t=curriculum.find(t=>t.id===id);if(!t)return;const l=state.learning[id]||{},qs=relatedQuestions(t);$('lessonpanel').innerHTML=`<article class="lesson-card" tabindex="-1"><button class="textbtn" id="lessonclose">一覧に戻る ↑</button><p class="eyebrow">${esc(catalogs[t.exam].name)} / ${esc(catalogs[t.exam].label(t.unit))}</p><h2>${esc(t.title)}</h2><p class="scope-note">${esc(t.area)}</p><h3>学習する範囲</h3><p>${esc(t.details)}</p>${t.scopeLimit?`<p class="scope-note">出題の程度：${esc(t.scopeLimitAppliesTo)} — ${esc(t.scopeLimit)}</p>`:""}<h3>到達目標・自己確認の問い</h3><ul>${learningPrompts(t).map(p=>`<li>${esc(p)}</li>`).join('')}</ul><p class="scope-note">自己確認は解説を閉じ、自分で説明・計算できるかを確かめて記録します。</p><div class="source-box"><a href="${esc(t.source)}${t.page?'#page='+t.page:''}" target="_blank" rel="noopener">対応する公式出題資料${t.page?'（'+t.page+'ページ）':''} ↗</a>${t.scope==='pending'?'<p>全経の公式詳細表との最終照合は未完了です。</p>':''}</div><h3>関連演習 ${qs.length}問</h3>${qs.length?`<p class="scope-note">この演習だけで、本項目すべての理解を判定することはできません。</p>${qs.map(q=>`<div class="lesson-question"><b>${esc(q.topic)}</b><details><summary>考え方を読む</summary><p>${esc(q.explain)}</p></details><button class="chip" data-lesson-practice="${esc(q.id)}">この問題を解く →</button></div>`).join('')}`:'<p class="scope-note">この項目に対応するサイト内演習は未収録です。未学習の範囲から除外せず、学習対象として残しています。</p>'}<h3>学習チェック</h3><div class="statusactions">${statusNames.map((name,i)=>`<button class="chip ${progressOf(t)===i?'selected':''}" data-learning-status="${i}">${name}</button>`).join('')}</div><p class="scope-note">自己申告の学習記録です。問題の正答率には加算されません。</p><label for="learningmemo">自分の言葉で、要点・間違えた理由を残す</label><textarea id="learningmemo" rows="4" maxlength="5000">${esc(l.memo||'')}</textarea><button class="primary" id="savememo">メモを保存する</button><p id="memosaved" role="status" class="muted"></p></article>`;
 document.querySelectorAll('[data-learning-status]').forEach(b=>b.onclick=()=>{state.learning[id]={...state.learning[id],status:+b.dataset.learningStatus,memo:$('learningmemo').value,updated:Date.now()};save();renderLearningStatus();renderCurriculum();openLesson(id)});document.querySelectorAll('[data-lesson-practice]').forEach(b=>b.onclick=()=>{const q=questions.find(q=>String(q.id)===b.dataset.lessonPractice);sessionStart=state.log.length;queue=[q];position=0;level=q.level;mode='practice';renderFilters();renderQuestion();navigate('practice')});$('savememo').onclick=()=>{state.learning[id]={...state.learning[id],memo:$('learningmemo').value,updated:Date.now()};save();$('memosaved').textContent='メモを保存しました。'};$('lessonclose').onclick=()=>{$('lessonpanel').innerHTML='';$('curriculumresults').scrollIntoView?.({behavior:'smooth'})};$('lessonpanel').scrollIntoView?.({behavior:'smooth',block:'start'});$('lessonpanel').querySelector?.('article')?.focus?.({preventScroll:true});
}
function exportCurriculum(){const rows=[['試験','級・科目','分野','論点','学習状況（自己申告）','関連演習数','範囲照合','公式資料'],...targetItems().map(t=>[catalogs[t.exam].name,catalogs[t.exam].label(t.unit),t.area,t.title,statusNames[progressOf(t)],relatedQuestions(t).length,t.scope==='pending'?'最終照合待ち':'出題表参照',t.source+(t.page?'#page='+t.page:'')])];const csv='\ufeff'+rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='book-keeping-curriculum-'+exam+'-'+curriculumUnit+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
