advice=function(){normalizeTarget();const next=targetItems().find(t=>progressOf(t)<2);return {label:next?'次の一項目を、確かな理解に。':'自己確認を、演習で確かめよう。',text:next?'次の学習候補：'+next.title:'自己確認を終えた項目も、初見問題・時間をあけた再テストで確認しましょう。',action:'カリキュラムを開く',curriculum:true,level:curriculumUnit}}
renderLearningStatus=function(){normalizeTarget();const host=$('learningstatus');if(!host)return;const s=progressSummary(),today=examLogs().filter(x=>x.date===day()),recoveries=examLogs().filter(x=>x.recovered).length;host.innerHTML=`<div class="statusbox"><div class="sectiontitle"><h2>${esc(unitLabel(curriculumUnit))}の学びの現在地</h2><span class="growthpill">一問の成果と、範囲の進捗を分けて見る。</span></div><div class="statusgrid"><div><span class="muted">着手した学習項目</span><strong>${s.started}<small class="muted"> / ${s.total}</small></strong></div><div><span class="muted">自己確認した項目</span><strong>${s.checked}<small class="muted"> / ${s.total}</small></strong></div><div><span class="muted">今日解いた問題</span><strong>${today.length}<small class="muted"> 問</small></strong></div></div><p>解き直して正解：${recoveries}回。ひとつずつ、できなかったことをできることに。</p><p class="scope-note">上の項目数は選択中の級・科目、解答数は選択中の試験の記録です。学習項目のチェックは自己申告です。${s.total-s.linked}項目は関連演習が未収録です。合格可能性を示す数値ではありません。</p><button class="primary" id="recommended">残りの学習項目を確認する ↗</button></div>`;$('recommended').onclick=()=>navigate('curriculum')}
const baseRenderDashboard=renderDashboard;renderDashboard=function(){baseRenderDashboard();document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{curriculumUnit=catalogs[exam].units.find(u=>String(u)===b.dataset.course);state.targets[exam]=curriculumUnit;level=curriculumUnit;queue=[];save();navigate('curriculum')});const label=$('courses')?.previousElementSibling?.querySelector?.('h2');if(label)label.textContent='級・科目別の学習項目';document.querySelectorAll('#courses .coursebody p').forEach((p,i)=>{const unit=catalogs[exam].units[i],items=curriculum.filter(t=>t.exam===exam&&t.unit===unit);p.textContent=items.length+' 学習チェック項目 / 関連演習を別途管理'});}
const baseRenderStats=renderStats;renderStats=function(){baseRenderStats();const s=progressSummary();$('statbody').innerHTML=`<div class="panel"><h2>${esc(unitLabel(curriculumUnit))}の範囲の進捗</h2><p>着手 ${s.started} / ${s.total}項目　自己確認 ${s.checked} / ${s.total}項目</p><p class="scope-note">以下の正答率は収録問題の成績です。出題範囲全体の習熟度ではありません。</p></div>`+$('statbody').innerHTML;}
